"""Version 1 schema. Applied via Alembic, never by importing the app."""
SCHEMA = '''
CREATE TABLE users(id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','teacher','student')), password_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', must_change INTEGER NOT NULL DEFAULT 1, auth_version INTEGER NOT NULL DEFAULT 1, watermark INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), auth_version INTEGER NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE login_attempts(key TEXT PRIMARY KEY, failures INTEGER NOT NULL, until_at TEXT);
CREATE TABLE audit_logs(id TEXT PRIMARY KEY, actor_id TEXT, action TEXT NOT NULL, target_id TEXT, detail TEXT, created_at TEXT NOT NULL);
CREATE TABLE classes(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'active', version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE memberships(class_id TEXT REFERENCES classes(id), user_id TEXT REFERENCES users(id), status TEXT NOT NULL DEFAULT 'active', PRIMARY KEY(class_id,user_id));
CREATE TABLE invites(id TEXT PRIMARY KEY, class_id TEXT REFERENCES classes(id), code_hash TEXT UNIQUE NOT NULL, expires_at TEXT NOT NULL, max_uses INTEGER NOT NULL, used INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE resources(id TEXT PRIMARY KEY, owner_id TEXT REFERENCES users(id), class_id TEXT REFERENCES classes(id), scope TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, tags TEXT NOT NULL, source_license TEXT NOT NULL, cloud_allowed INTEGER NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', current_version TEXT, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE resource_versions(id TEXT PRIMARY KEY, resource_id TEXT REFERENCES resources(id), filename TEXT NOT NULL, storage_key TEXT, mime TEXT, bytes INTEGER NOT NULL, hash TEXT NOT NULL, body TEXT NOT NULL, parse_status TEXT NOT NULL, index_status TEXT NOT NULL, error TEXT, created_at TEXT NOT NULL);
CREATE TABLE transcripts(id TEXT PRIMARY KEY, version_id TEXT REFERENCES resource_versions(id), body TEXT NOT NULL, filename TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE VIRTUAL TABLE chunks USING fts5(resource_id UNINDEXED, version_id UNINDEXED, body, tokenize='unicode61');
CREATE TABLE study_sessions(id TEXT PRIMARY KEY, student_id TEXT REFERENCES users(id), resource_id TEXT REFERENCES resources(id), class_id TEXT, minutes INTEGER NOT NULL CHECK(minutes>0), completed INTEGER NOT NULL, created_at TEXT NOT NULL, UNIQUE(student_id,resource_id,id));
CREATE TABLE tasks(id TEXT PRIMARY KEY, owner_id TEXT REFERENCES users(id), class_id TEXT REFERENCES classes(id), title TEXT NOT NULL, description TEXT NOT NULL, due_at TEXT NOT NULL, minutes INTEGER NOT NULL CHECK(minutes>0), mode TEXT NOT NULL, resource_id TEXT REFERENCES resources(id), questions TEXT NOT NULL, recipients TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE assignments(id TEXT PRIMARY KEY, task_id TEXT REFERENCES tasks(id), student_id TEXT REFERENCES users(id), status TEXT NOT NULL DEFAULT 'not_started', first_completed_at TEXT, UNIQUE(task_id,student_id));
CREATE TABLE attempts(id TEXT PRIMARY KEY, assignment_id TEXT UNIQUE REFERENCES assignments(id), student_id TEXT REFERENCES users(id), goal_id TEXT, class_id TEXT, answers TEXT NOT NULL, feedback TEXT NOT NULL, status TEXT NOT NULL, score REAL, minutes INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE grades(id TEXT PRIMARY KEY, attempt_id TEXT REFERENCES attempts(id), version INTEGER NOT NULL, score REAL NOT NULL, comment TEXT NOT NULL, grader_id TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(attempt_id,version));
CREATE TABLE observations(id TEXT PRIMARY KEY, attempt_id TEXT REFERENCES attempts(id), student_id TEXT REFERENCES users(id), class_id TEXT, skill TEXT NOT NULL, correct INTEGER NOT NULL, sequence INTEGER NOT NULL, UNIQUE(attempt_id,skill,sequence));
CREATE TABLE mastery_snapshots(id TEXT PRIMARY KEY, student_id TEXT, class_id TEXT, skill TEXT, probability REAL, evidence_count INTEGER, created_at TEXT);
CREATE TABLE budgets(user_id TEXT PRIMARY KEY REFERENCES users(id), daily_minutes INTEGER NOT NULL DEFAULT 120, weekly_minutes INTEGER NOT NULL DEFAULT 600, timezone TEXT NOT NULL DEFAULT 'Asia/Shanghai', days TEXT NOT NULL DEFAULT '[0,1,2,3,4,5,6]', version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE goals(id TEXT PRIMARY KEY, student_id TEXT REFERENCES users(id), title TEXT NOT NULL, skills TEXT NOT NULL, weekly_minutes INTEGER NOT NULL, due_date TEXT NOT NULL, class_id TEXT REFERENCES classes(id), status TEXT NOT NULL DEFAULT 'draft', version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE diagnoses(id TEXT PRIMARY KEY, goal_id TEXT REFERENCES goals(id), student_id TEXT, questions TEXT NOT NULL, attempt_id TEXT REFERENCES attempts(id), draft_answers TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE paths(id TEXT PRIMARY KEY, goal_id TEXT REFERENCES goals(id), student_id TEXT REFERENCES users(id), status TEXT NOT NULL, content_status TEXT NOT NULL, tasks TEXT NOT NULL, sources TEXT NOT NULL, validation TEXT NOT NULL, fingerprint TEXT NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE UNIQUE INDEX one_active_path ON paths(goal_id) WHERE status='active';
CREATE TABLE reservations(id TEXT PRIMARY KEY, student_id TEXT REFERENCES users(id), source_type TEXT NOT NULL, source_id TEXT NOT NULL, goal_id TEXT, local_date TEXT NOT NULL, minutes INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE checkins(id TEXT PRIMARY KEY, student_id TEXT REFERENCES users(id), path_id TEXT REFERENCES paths(id), item_id TEXT NOT NULL, minutes INTEGER NOT NULL, proportion REAL NOT NULL, difficulty TEXT NOT NULL, note TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(path_id,item_id));
CREATE TABLE profile_snapshots(id TEXT PRIMARY KEY, scope TEXT NOT NULL, scope_id TEXT NOT NULL, watermark TEXT NOT NULL, payload TEXT NOT NULL, version INTEGER NOT NULL, created_at TEXT NOT NULL, UNIQUE(scope,scope_id,watermark));
CREATE TABLE model_configs(id TEXT PRIMARY KEY, model TEXT NOT NULL, endpoint TEXT NOT NULL, secret_env TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'registered', evaluation TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
CREATE TABLE agent_runs(id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id), goal_id TEXT, kind TEXT NOT NULL, status TEXT NOT NULL, result_id TEXT, error TEXT, checkpoint TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, finished_at TEXT, idem_key TEXT NOT NULL, UNIQUE(actor_id,kind,idem_key));
CREATE TABLE agent_steps(id TEXT PRIMARY KEY, run_id TEXT REFERENCES agent_runs(id), agent TEXT NOT NULL, status TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL);
'''
